<script setup>
/* eslint-env vue/setup-compiler-macros */
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import { right } from "@popperjs/core";

import questionIcon from "@/assets/icons/question.svg";

const props = defineProps({
  isIata: {
    type: Boolean,
    required: true,
  },
  rows: {
    type: Array,
    required: true,
  },
});

const selectedFlight = ref(null);

function getFlightCode(row) {
  return props.isIata ? row.Flight : row.CallSign;
}

function getAirportCode(airport) {
  return props.isIata ? airport.iata : airport.icao;
}

function openFlightDetails(row) {
  selectedFlight.value = row;
}

function closeFlightDetails() {
  selectedFlight.value = null;
}

function handleKeydown(event) {
  if (event.key === "Escape" && selectedFlight.value) {
    closeFlightDetails();
  }
}

watch(selectedFlight, (row) => {
  document.body.style.overflow = row ? "hidden" : "";
});

onMounted(() => {
  window.addEventListener("keydown", handleKeydown);
});

onBeforeUnmount(() => {
  window.removeEventListener("keydown", handleKeydown);
  document.body.style.overflow = "";
});
</script>

<template>
  <div class="gallery-view">
    <button
      v-for="row in rows"
      :key="row.id"
      class="gallery-image-container"
      type="button"
      @click="openFlightDetails(row)"
    >
      <div class="image-wrapper">
        <img :src="row.imageUrl" alt="aircraft" class="gallery-image" />

        <div class="image-caption">
          <div class="caption-topline">
            <span class="caption-date">{{ row.Date }}</span>
            <span class="caption-flight">{{ getFlightCode(row) }}</span>
          </div>
          <div class="caption-route">
            {{ getAirportCode(row.fromAirport) }} -
            {{ getAirportCode(row.toAirport) }}
          </div>
          <div class="caption-subline">
            <span>{{ row.Aircraft }}</span>
            <span class="caption-detail-link">View details</span>
          </div>
        </div>

        <div
          v-if="row.registrationInfo.isUnknown"
          class="unknown-reg"
          v-tooltip="{
            content: 'unknown reg',
            placement: right,
          }"
        >
          <img :src="questionIcon" class="gallery-icon" />
        </div>
      </div>
    </button>

    <div
      v-if="selectedFlight"
      class="detail-backdrop"
      @click="closeFlightDetails"
    >
      <div class="detail-modal" @click.stop>
        <button class="detail-close" type="button" @click="closeFlightDetails">
          Close
        </button>

        <div class="detail-media">
          <img
            :src="selectedFlight.imageUrl"
            alt="aircraft"
            class="detail-image"
          />
        </div>

        <div class="detail-content">
          <div class="detail-kicker">
            {{ selectedFlight.airlineDisplayName }}
          </div>
          <h3 class="detail-title">
            {{ getAirportCode(selectedFlight.fromAirport) }} -
            {{ getAirportCode(selectedFlight.toAirport) }}
          </h3>
          <p class="detail-subtitle">
            {{ selectedFlight.Aircraft }}
          </p>

          <div class="detail-grid">
            <div class="detail-item">
              <span class="detail-label">Date</span>
              <span class="detail-value">{{ selectedFlight.Date }}</span>
            </div>
            <div class="detail-item">
              <span class="detail-label">{{
                isIata ? "Flight" : "Call Sign"
              }}</span>
              <span class="detail-value">{{
                getFlightCode(selectedFlight)
              }}</span>
            </div>
            <div class="detail-item">
              <span class="detail-label">Route</span>
              <span class="detail-value">
                {{ getAirportCode(selectedFlight.fromAirport) }} -
                {{ getAirportCode(selectedFlight.toAirport) }}
              </span>
            </div>
            <div class="detail-item">
              <span class="detail-label">Registration</span>
              <span class="detail-value">
                {{ selectedFlight.registrationInfo.tailNumber }}
              </span>
            </div>
            <div class="detail-item">
              <span class="detail-label">Miles</span>
              <span class="detail-value">{{ selectedFlight.Miles }}</span>
            </div>
            <div class="detail-item">
              <span class="detail-label">Aircraft</span>
              <span class="detail-value">{{ selectedFlight.Aircraft }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="gallery-credit">Image Credit: JetPhotos Photographers</div>
  </div>
</template>

