import { computed, ref, watch } from "vue";

import {
  FLIGHT_LOG_COLUMNS,
  ITEMS_PER_PAGE,
  SORTABLE_COLUMNS,
} from "@/constants/flightLog";
import {
  buildFlightLogSummary,
  filterFlightLogRows,
  getFlightLogRows,
  sortFlightLogRows,
} from "@/utils/flightLog";

const flightLogRows = getFlightLogRows();

const SORT_OPTIONS = [
  { label: "Date", value: "Date" },
  { label: "Miles", value: "Miles" },
  { label: "Airline", value: "Airline" },
  { label: "Flight", value: "Flight" },
  { label: "Call Sign", value: "CallSign" },
  { label: "Aircraft", value: "Aircraft" },
  { label: "Registration", value: "Registration" },
];

export function useFlightLogData() {
  const currentPage = ref(1);
  const isGalleryView = ref(false);
  const isIata = ref(false);
  const searchQuery = ref("");
  const selectedAirline = ref("all");
  const selectedYear = ref("all");
  const sortBy = ref("Date");
  const sortOrder = ref("desc");

  const visibleColumns = computed(() => {
    const hiddenColumn = isIata.value ? "CallSign" : "Flight";

    return FLIGHT_LOG_COLUMNS.filter((column) => column !== hiddenColumn);
  });

  const airlineOptions = computed(() => [
    { label: "All Airlines", value: "all" },
    ...[
      ...new Map(
        flightLogRows.map((row) => [
          row.marketingAirlineCode,
          {
            label: row.airlineDisplayName,
            value: row.marketingAirlineCode,
          },
        ]),
      ).values(),
    ].sort((a, b) => a.label.localeCompare(b.label)),
  ]);

  const yearOptions = computed(() => [
    { label: "All Years", value: "all" },
    ...[...new Set(flightLogRows.map((row) => String(row.Date).slice(0, 4)))]
      .sort((a, b) => b.localeCompare(a))
      .map((year) => ({
        label: year,
        value: year,
      })),
  ]);

  const filteredRows = computed(() =>
    filterFlightLogRows(flightLogRows, {
      airline: selectedAirline.value,
      search: searchQuery.value,
      year: selectedYear.value,
    }),
  );

  const sortedRows = computed(() =>
    sortFlightLogRows(filteredRows.value, sortBy.value, sortOrder.value),
  );

  const totalPages = computed(() =>
    Math.max(1, Math.ceil(sortedRows.value.length / ITEMS_PER_PAGE)),
  );

  const paginatedRows = computed(() => {
    const start = (currentPage.value - 1) * ITEMS_PER_PAGE;

    return sortedRows.value.slice(start, start + ITEMS_PER_PAGE);
  });

  const summary = computed(() =>
    buildFlightLogSummary(filteredRows.value, flightLogRows),
  );

  function toggleSortByColumn(column) {
    if (sortBy.value === column) {
      sortOrder.value = sortOrder.value === "asc" ? "desc" : "asc";
      return;
    }

    sortBy.value = column;
    sortOrder.value = "desc";
  }

  function setSortColumn(column) {
    sortBy.value = column;
  }

  function setSortOrder(order) {
    sortOrder.value = order;
  }

  function goToPage(page) {
    if (page >= 1 && page <= totalPages.value) {
      currentPage.value = page;
    }
  }

  watch(isGalleryView, (enabled) => {
    if (!enabled) {
      return;
    }

    sortBy.value = "Date";
    sortOrder.value = "desc";
  });

  watch([searchQuery, selectedAirline, selectedYear, sortBy, sortOrder], () => {
    currentPage.value = 1;
  });

  watch(totalPages, (pageCount) => {
    if (currentPage.value > pageCount) {
      currentPage.value = pageCount;
    }
  });

  return {
    airlineOptions,
    currentPage,
    filteredRows,
    goToPage,
    isGalleryView,
    isIata,
    itemsPerPage: ITEMS_PER_PAGE,
    paginatedRows,
    searchQuery,
    selectedAirline,
    selectedYear,
    setSortColumn,
    setSortOrder,
    sortBy,
    sortOrder,
    sortOptions: SORT_OPTIONS,
    sortableColumns: SORTABLE_COLUMNS,
    summary,
    toggleSortByColumn,
    totalPages,
    totalRows: flightLogRows.length,
    visibleColumns,
    yearOptions,
  };
}
