export function getAirlineCodes(value = "") {
  const [marketingLogoCode = "", operatingCode = marketingLogoCode] =
    value.split("-");
  const marketingCode = marketingLogoCode.substring(0, 3);

  return {
    marketingCode,
    marketingLogoCode: marketingLogoCode || marketingCode,
    operatingCode: operatingCode.substring(0, 3),
  };
}

export function getAirportDetails(code = "", airports = {}) {
  const airport = airports[code];

  if (!airport) {
    return {
      iata: code,
      icao: code,
      name: code,
      flagCode: "undefined",
    };
  }

  return {
    iata: code,
    ...airport,
  };
}

export function getRegistrationDetails(value = "") {
  const [countryCode = "", tailNumber = "", photoPath = ""] = value.split("|");

  return {
    countryCode,
    tailNumber,
    photoPath,
    isUnknown: tailNumber.includes("?"),
  };
}

export function buildCallSign(row, operatingCode) {
  if (row.CallSign) {
    return row.CallSign;
  }

  return `${operatingCode}${String(row.Flight || "").substring(2)}`;
}

export function normalizeFlightLogRow(row, index, options = {}) {
  const { airlines = {}, airports = {}, columns = [] } = options;
  const airlineCodes = getAirlineCodes(row.Airline);
  const registrationInfo = getRegistrationDetails(row.Registration);
  const marketingAirlineDisplayName =
    airlines[airlineCodes.marketingCode] || airlineCodes.marketingCode;
  const operatingAirlineDisplayName =
    airlines[airlineCodes.operatingCode] || airlineCodes.operatingCode;

  return {
    ...Object.fromEntries(columns.map((column) => [column, row[column] || ""])),
    id: `${row.Date}-${row.Flight}-${index}`,
    originalIndex: index,
    CallSign: buildCallSign(row, airlineCodes.operatingCode),
    Miles: row.Miles || "0",
    airlineDisplayName: marketingAirlineDisplayName,
    airlineLogoCode: airlineCodes.marketingLogoCode,
    marketingAirlineCode: airlineCodes.marketingCode,
    marketingAirlineDisplayName,
    operatingAirlineCode: airlineCodes.operatingCode,
    operatingAirlineDisplayName,
    fromAirport: getAirportDetails(row.From, airports),
    toAirport: getAirportDetails(row.To, airports),
    registrationInfo,
    imageUrl: registrationInfo.photoPath
      ? `https://cdn.jetphotos.com/full${registrationInfo.photoPath}`
      : "",
    previewImageUrl: registrationInfo.photoPath
      ? `https://cdn.jetphotos.com/400${registrationInfo.photoPath}`
      : "",
  };
}

export function sortFlightLogRows(rows, sortBy, sortOrder) {
  const direction = sortOrder === "asc" ? 1 : -1;

  return [...rows].sort((a, b) => {
    let comparison = 0;

    if (sortBy === "Miles") {
      comparison = Number(a.Miles) - Number(b.Miles);
    } else {
      comparison = String(a[sortBy] || "").localeCompare(String(b[sortBy] || ""));
    }

    if (comparison !== 0) {
      return comparison * direction;
    }

    return a.originalIndex - b.originalIndex;
  });
}

export function filterFlightLogRows(rows, filters = {}) {
  const {
    airline = "all",
    search = "",
    year = "all",
  } = filters;
  const normalizedSearch = search.trim().toLowerCase();

  return rows.filter((row) => {
    if (airline !== "all" && row.marketingAirlineCode !== airline) {
      return false;
    }

    if (year !== "all" && String(row.Date || "").slice(0, 4) !== year) {
      return false;
    }

    if (!normalizedSearch) {
      return true;
    }

    const haystack = [
      row.Date,
      row.Airline,
      row.airlineDisplayName,
      row.airlineLogoCode,
      row.marketingAirlineCode,
      row.marketingAirlineDisplayName,
      row.operatingAirlineCode,
      row.operatingAirlineDisplayName,
      row.Flight,
      row.CallSign,
      row.Aircraft,
      row.Registration,
      row.registrationInfo?.tailNumber,
      row.fromAirport?.iata,
      row.fromAirport?.icao,
      row.fromAirport?.name,
      row.toAirport?.iata,
      row.toAirport?.icao,
      row.toAirport?.name,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return haystack.includes(normalizedSearch);
  });
}

export function buildFlightLogSummary(rows, allRows = rows) {
  const miles = rows.reduce((sum, row) => sum + Number(row.Miles || 0), 0);
  const airports = new Set();
  const airlines = new Set();

  rows.forEach((row) => {
    if (row.fromAirport?.iata) {
      airports.add(row.fromAirport.iata);
    }
    if (row.toAirport?.iata) {
      airports.add(row.toAirport.iata);
    }
    if (row.marketingAirlineCode) {
      airlines.add(row.marketingAirlineCode);
    }
  });

  const latestFlight = [...rows]
    .sort((a, b) => String(b.Date || "").localeCompare(String(a.Date || "")))[0]
    ?.Date;

  return {
    airlinesCount: airlines.size,
    filteredFlights: rows.length,
    latestFlight: latestFlight || "N/A",
    totalAirports: airports.size,
    totalFlights: allRows.length,
    totalMiles: miles,
  };
}
